mapper.select:
SELECT *
FROM app_permission
WHERE permission_code = #{permissionCode}

  AND status = #{status}

ORDER BY id ASC
LIMIT 1

SELECT *
FROM app_permission
WHERE module_code = #{moduleCode}
  AND status = #{status}
ORDER BY permission_code ASC, id ASC

SELECT *
FROM app_permission
WHERE permission_code IN

  #{code}

  AND status = #{status}
ORDER BY permission_code ASC, id ASC

SELECT EXISTS (
  SELECT 1
  FROM app_permission
  WHERE permission_code = #{permissionCode}
    AND status = #{status}
)

SELECT * FROM app_permission WHERE id IN
#{id}
ORDER BY id ASC
